//! Port of `pkg/fontconfig/c.zig`.
//!
//! STATUS: ported
//!
//! The Zig package translate-c's `fontconfig/fontconfig.h`. The Rust
//! equivalent is `c_bindings.rs`, generated by rust-bindgen 0.73 from the
//! same header of the system fontconfig (allowlist `Fc.*|FC_.*|_Fc.*`, enum
//! constants without the enum name prefix) and linked via pkg-config in
//! `build.rs`. Zig's `c.struct__FcPattern` etc. are `c::_FcPattern` here.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]

include!("c_bindings.rs");
